import random as _rnd


def _tape(n, seed, rare="ZZZ"):
    # n tickers from 25 random ones (AAA to YYY); the rare ticker appears only as the last trade
    g = _rnd.Random(seed)
    names = [chr(65 + i) * 3 for i in range(25)]
    xs = [g.choice(names) for _ in range(n - 1)]
    return xs + [rare]


class _Counted(list):
    reads = 0

    def __getitem__(self, i):
        _Counted.reads += 1
        return list.__getitem__(self, i)

    def __iter__(self):
        _Counted.reads += len(self)
        return list.__iter__(self)


def reads_for(fn, xs, *rest):
    _Counted.reads = 0
    fn(_Counted(xs), *rest)
    return _Counted.reads


