def shortest_cover(tickers, needed):
    need = set(needed)
    count = {}
    have = 0
    best = -1
    left = 0
    for right, t in enumerate(tickers):
        if t in need:
            count[t] = count.get(t, 0) + 1
            if count[t] == 1:
                have += 1
        while have == len(need):
            if best == -1 or right - left + 1 < best:
                best = right - left + 1
            u = tickers[left]
            if u in need:
                count[u] -= 1
                if count[u] == 0:
                    have -= 1
            left += 1
    return best

