def can_ship(weights, k, cap):
    days, load = 1, 0
    for w in weights:
        if w > cap:
            return False
        if load + w > cap:
            days += 1
            load = 0
        load += w
    return days <= k


def min_capacity(weights, k):
    lo, hi = max(weights), sum(weights)
    while lo < hi:
        mid = (lo + hi) // 2
        if can_ship(weights, k, mid):
            hi = mid
        else:
            lo = mid + 1
    return lo

